const byName = new Map(MARKS.flatMap((m) => m.names.map((n) => [n, m] as const)));
const byDomain = new Map(MARKS.flatMap((m) => m.domains.map((d) => [d, m] as const)));

export const brandMarkFor = (brand: string | null | undefined): BrandMark | null => (brand ? byName.get(brand.trim().toLowerCase()) ?? null : null);

/** For a store domain (or any subdomain of one). */
export function storeMarkFor(domain: string | null | undefined): BrandMark | null {
  if (!domain) return null;
  let d = domain.toLowerCase();
  for (;;) {
    const m = byDomain.get(d);
    if (m) return m;
    const i = d.indexOf(".");
    if (i < 0 || d.indexOf(".", i + 1) < 0) return null;
    d = d.slice(i + 1);
  }
}
